"""Tests for the root files generated by the package exporter."""

from __future__ import annotations

import sys
import tempfile
import unittest
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(REPO_ROOT / "bin"))

from package_export import export_stack  # noqa: E402


class ExportRootFilesTests(unittest.TestCase):
    def test_export_writes_expected_root_files(self) -> None:
        with tempfile.TemporaryDirectory() as temp_dir:
            destination = Path(temp_dir) / "test-stack"
            export_stack(["memcached"], "test-stack", root=REPO_ROOT, destination=destination)

            self.assertEqual(
                (destination / ".python-version").read_bytes(),
                (REPO_ROOT / ".python-version").read_bytes(),
            )
            self.assertEqual(
                (destination / "pyproject.toml").read_text(encoding="utf-8"),
                "[project]\n"
                'name = "docker-shared-services"\n'
                'version = "0.1.0"\n'
                'description = "Packaged Docker Shared Services stack"\n'
                'requires-python = ">=3.12"\n'
                "dependencies = []\n"
                "\n"
                "[tool.uv]\n"
                "package = false\n",
            )
            self.assertEqual(
                (destination / ".gitignore").read_text(encoding="utf-8"),
                "# Environment & secrets\n"
                ".env\n"
                ".env.local\n"
                ".env.production\n"
                ".env.*.local\n"
                ".env.test\n"
                "!.env.example\n"
                "!**/.env.example\n"
                "\n"
                "# Runtime data\n"
                "**/data/\n"
                "**/*_data/\n"
                "dozzle/data/\n"
                "supabase/volumes/db/data/\n"
                "supabase/volumes/storage/\n"
                "\n"
                "# Certificates\n"
                "traefik/certs/*.crt\n"
                "traefik/certs/*.key\n"
                "**/server.crt\n"
                "**/server.key\n"
                "\n"
                "# Logs, temp, OS\n"
                "*.log\n"
                "logs/\n"
                "*.tmp\n"
                "tmp/\n"
                "temp/\n"
                ".DS_Store\n"
                "Thumbs.db\n"
                "\n"
                "# Python\n"
                ".venv/\n"
                "**/__pycache__/\n"
                "*.py[cod]\n",
            )
            self.assertFalse((destination / ".ignore").exists())
            self.assertFalse((destination / ".dockerignore").exists())


if __name__ == "__main__":
    unittest.main()
